class Solution:
    def getChain(self, start, end):
        """
        :param start:
        :param end:
        :return:
        """
        stack = []
        stack.append(start)
        stack.append(end)
        while stack:
            start, end = stack.pop()
            if start == end:
                stack.pop()
            else:
                stack.append(start)
            stack.append(end)
        return ','.join(stack)
